function v51Day2Stop(id){for(let i=0;i<V51_STOPS.length;i++)if(V51_STOPS[i][1].includes(id))return i;return id>=22?V51_STOPS.length-1:0}
function v51Dist(a,b){const R=6371,t=x=>x*Math.PI/180,dl=t(b[0]-a[0]),dn=t(b[1]-a[1]),h=Math.sin(dl/2)**2+Math.cos(t(a[0]))*Math.cos(t(b[0]))*Math.sin(dn/2)**2;return 2*R*Math.asin(Math.sqrt(h))}
function v51XY(lat,lon){return [(lon-V51_MAP.LON0)*V51_MAP.k*V51_MAP.sx,(V51_MAP.LAT1-lat)*V51_MAP.sx]}

/* zonsopkomst/-ondergang (NOAA-benadering), lokale tijd UTC-6 */
function v51Sun(lat,lon,iso){const d=new Date(iso+'T12:00:00Z'),N=Math.floor((d-Date.UTC(d.getUTCFullYear(),0,0))/864e5),rad=Math.PI/180,lngH=lon/15;
  const calc=rise=>{const t=N+((rise?6:18)-lngH)/24,M=0.9856*t-3.289;let L=(M+1.916*Math.sin(M*rad)+0.020*Math.sin(2*M*rad)+282.634)%360;if(L<0)L+=360;
    let RA=Math.atan(0.91764*Math.tan(L*rad))/rad;RA=(RA+360)%360;RA+=Math.floor(L/90)*90-Math.floor(RA/90)*90;RA/=15;
    const sinD=0.39782*Math.sin(L*rad),cosD=Math.cos(Math.asin(sinD)),cosH=(Math.cos(90.833*rad)-sinD*Math.sin(lat*rad))/(cosD*Math.cos(lat*rad));
    let H=Math.acos(cosH)/rad;H=(rise?360-H:H)/15;const T=H+RA-0.06571*t-6.622;let UT=(T-lngH)%24;if(UT<0)UT+=24;let loc=(UT-6+24)%24;
    const h=Math.floor(loc),m=Math.round((loc-h)*60);return String(h+(m===60?1:0)).padStart(2,'0')+':'+String(m%60).padStart(2,'0')};
  return {rise:calc(true),set:calc(false)}}

/* ---------- SVG-kaart ---------- */
let v51Pos=null,v51Watch=null;
function v51Svg(focusDay){
  const M=V51_MAP,P=n=>v51XY(V51_PT[n][0],V51_PT[n][1]),cur=focusDay?v51Day2Stop(focusDay):-1;
  const legs=V51_LEGS.map(([a,b,m])=>{const[x1,y1]=P(a),[x2,y2]=P(b);return `<line x1="${x1.toFixed(1)}" y1="${y1.toFixed(1)}" x2="${x2.toFixed(1)}" y2="${y2.toFixed(1)}" class="${m==='boot'?'v51-boat':'v51-road'}"/>`}).join('');
  const tracks=(state.gpsTracks||[]).map(t=>{const pts=(t.points||[]).map(p=>Array.isArray(p)?p:[p.lat,p.lon]).filter(p=>p[0]&&p[1]).map(p=>v51XY(p[0],p[1]).map(v=>v.toFixed(1)).join(','));return pts.length>1?`<polyline points="${pts.join(' ')}" class="v51-track"/>`:''}).join('');
  const stops=V51_STOPS.map(([r,days],i)=>{if(i===V51_STOPS.length-1)return '';const[x,y]=P(r),on=i===cur;return `<g class="v51-stop ${on?'on':''}" data-v51-day="${days[0]}"><circle cx="${x.toFixed(1)}" cy="${y.toFixed(1)}" r="${on?13:10}"/><text x="${x.toFixed(1)}" y="${(y+4).toFixed(1)}">${i+1}</text></g>`}).join('');
  const labels=V51_STOPS.slice(0,-1).map(([r],i)=>{const[x,y]=P(r),left=['Cahuita','Tortuguero','Esterillos','Corcovado'].includes(r);return `<text class="v51-lbl ${i===cur?'on':''}" x="${(x+(left?-16:16)).toFixed(1)}" y="${(y+4).toFixed(1)}" text-anchor="${left?'end':'start'}">${esc(V51_PT[r][2])}</text>`}).join('');
  const exc=Object.entries(V51_EXC).flatMap(([d,list])=>list.map(n=>{const[x,y]=P(n),on=+d===focusDay;return `<g class="v51-exc ${on?'on':''}"><circle cx="${x.toFixed(1)}" cy="${y.toFixed(1)}" r="${on?7:5}"/>${on?`<text x="${(x+10).toFixed(1)}" y="${(y+4).toFixed(1)}">${esc(V51_PT[n][2])}</text>`:''}</g>`})).join('');
  const sjo=P('SJO');
  const me=v51Pos?(()=>{const[x,y]=v51XY(v51Pos.lat,v51Pos.lon);return x>-20&&x<M.W+20&&y>-20&&y<M.H+20?`<g class="v51-me"><circle cx="${x.toFixed(1)}" cy="${y.toFixed(1)}" r="16" class="pulse"/><circle cx="${x.toFixed(1)}" cy="${y.toFixed(1)}" r="7"/></g>`:''})():'';
  return `<svg class="v51-svg" viewBox="0 0 ${M.W} ${M.H}" role="img" aria-label="Routekaart Costa Rica">
    <rect width="${M.W}" height="${M.H}" class="v51-sea"/>
    <path d="${M.NIC}" class="v51-nb"/><path d="${M.PAN}" class="v51-nb"/><path d="${M.CRI}" class="v51-land"/>
    <text x="70" y="40" class="v51-cty">NICARAGUA</text><text x="${M.W-90}" y="${M.H-24}" class="v51-cty">PANAMA</text>
    <text x="${M.W-120}" y="120" class="v51-sea-lbl">Caribische Zee</text><text x="40" y="${M.H-60}" class="v51-sea-lbl">Grote Oceaan</text>
    ${tracks}${legs}<g class="v51-air"><path d="M${(sjo[0]-6).toFixed(1)},${sjo[1].toFixed(1)}h12M${sjo[0].toFixed(1)},${(sjo[1]-6).toFixed(1)}v12"/></g>${exc}${stops}${labels}${me}
  </svg>`}
function v51Legend(){return `<div class="v51-legend"><span><i class="l-road"></i>Bus (hemelsbreed)</span><span><i class="l-boat"></i>Boot</span><span><i class="l-exc"></i>Excursie</span><span><i class="l-me"></i>Jij</span></div>`}
function v51Nav(name,lat,lon){const q=encodeURIComponent(name+', Costa Rica');return `<div class="v51-navbtns"><a href="https://www.google.com/maps/dir/?api=1&destination=${lat},${lon}" target="_blank" rel="noopener">${v50I('pin',15)}Google Maps</a><a href="https://waze.com/ul?ll=${lat},${lon}&navigate=yes" target="_blank" rel="noopener">${v50I('pin',15)}Waze</a><a href="https://www.google.com/maps/search/?api=1&query=${q}" target="_blank" rel="noopener">${v50I('list',15)}Zoek plek</a></div>`}
function v51GpsBox(){const s=v51Watch!==null;return `<div class="v51-gps"><button id="v51gps" class="${s?'on':''}">${v50I('pin',16)}${s?'Live positie aan':'Toon mijn positie'}</button><span id="v51gpsinfo">${v51Pos?`${v51Pos.lat.toFixed(4)}, ${v51Pos.lon.toFixed(4)} · ±${Math.round(v51Pos.acc)} m`:'Werkt ook zonder internet (GPS)'}</span></div>`}

/* ---------- reisinformatie per dag ---------- */
function v51Info(d){
  const si=v51Day2Stop(d.id),stop=V51_STOPS[si][0],pt=V51_PT[stop],prev=si>0&&V51_STOPS[si][1][0]===d.id?V51_STOPS[si-1][0]:null;
  const tr=V51_TRAVEL[d.id],km=prev?Math.round(v51Dist(V51_PT[prev],pt)):null,clim=V51_CLIM[v47Region(d)]||V51_CLIM[stop],sun=v51Sun(pt[0],pt[1],d.date);
  const row=(ic,t,v,s)=>`<div class="v51-row"><span class="v51-ic">${ic}</span><div><b>${t}</b><span>${v}</span>${s?`<small>${s}</small>`:''}</div></div>`;
  const climTxt=!clim?'—':clim.txt?esc(clim.txt):`${String(clim.lo).replace('.',',')}–${String(clim.hi).replace('.',',')} °C · ${String(clim.mm).replace('.',',')} mm${clim.dd!=null?' · '+String(clim.dd).replace('.',',')+' regendagen':''}`;
  return `<div class="card v51-info"><div class="v50-h">Reisinformatie</div>
    ${row(v46Icon(tr?.m==='boat'?'boat':tr?.m==='plane'?'plane':'bus',20),'Reistijd',tr?esc(tr.t):'Geen transfer vandaag',tr?'Volgens Sawadee-reisroute':'')}
    ${km?row(v50I('pin',20),'Afstand (hemelsbreed)',`± ${km} km hemelsbreed vanaf ${esc(V51_PT[prev][2])}`,'Over de weg is het verder'):''}
    ${row(V46_SVG('<path d="m3 20 6-10 4 6 3-4 5 8z"/>').replace('width="24" height="24"','width="20" height="20"'),'Hoogte',esc(V51_ELEV[v47Region(d)]||V51_ELEV[stop]||'—'),'')}
    ${row(v50I('clock',20).replace(V50_I.clock,'<circle cx="12" cy="12" r="4"/><path d="M12 2v2M12 20v2M4.9 4.9l1.4 1.4M17.7 17.7l1.4 1.4M2 12h2M20 12h2M4.9 19.1l1.4-1.4M17.7 6.3l1.4-1.4"/>'),'Zon op / onder',`${sun.rise} / ${sun.set}`,'Berekend voor '+esc(pt[2])+', lokale tijd')}
    ${row(V46_SVG('<path d="M7 18a5 5 0 1 1 .9-9.9A6 6 0 0 1 19 10a4 4 0 0 1-1 8z"/><path d="M9 21l1-2M13 21l1-2"/>').replace('width="24" height="24"','width="20" height="20"'),'Klimaat in februari',climTxt,clim?.src?esc(clim.src):'')}
  </div>`}

/* dag-in-het-kort op het overzicht */
function v51Brief(d){const tr=V51_TRAVEL[d.id],fixed=d.activities.filter(a=>v50Kind(a)==='saw'||a.status==='locked').length,opt=d.activities.filter(a=>v50Kind(a)==='opt').length,todo=d.activities.filter((a,i)=>['online','zelf'].includes(v48BookOf(a,d,i))&&a.status!=='excluded').length,sun=v51Sun(V51_PT[V51_STOPS[v51Day2Stop(d.id)][0]][0],V51_PT[V51_STOPS[v51Day2Stop(d.id)][0]][1],d.date);
  const t=(ic,v,l,warn)=>`<div class="v51-tile ${warn?'warn':''}">${ic}<b>${v}</b><small>${l}</small></div>`;
  return `<div class="v51-brief">${t(v46Icon(tr?.m==='boat'?'boat':tr?.m==='plane'?'plane':'bus',18),tr?esc(tr.t.replace(/^ca\. /,'').split(' (')[0].split(':').pop().trim()):'—','reistijd')}${t(v50I('lock',18),fixed,'vast')}${t(v50I('plus',18),opt,'optioneel')}${t(v50I('alert',18),todo,'te regelen',todo>0)}</div><div class="v51-sunline">${v50I('clock',14)}Zon op ${sun.rise} · onder ${sun.set}</div>`}
const v51PrevDC=dayContent;
dayContent=function(d){
  if(daySection==='overview'){return v51PrevDC(d).replace('<div class="v50-timeline">',v51Brief(d)+'<div class="v50-timeline">')}
  if(daySection==='map'){const si=v51Day2Stop(d.id),stop=V51_STOPS[si][0],pt=V51_PT[stop];
    return `<div class="card v51-mapcard"><div class="v51-maphead"><div class="v50-h">Locatie & kaart</div>${v51GpsBox()}</div>${v51Svg(d.id)}${v51Legend()}<p class="hint" style="margin:6px 0 0">Offline kaart. Locaties bij benadering; lijnen hemelsbreed, niet de rijroute.</p></div>
    <div class="card"><div class="v50-h" style="font-size:16px">Navigeer naar ${esc(pt[2])}</div><p class="hint" style="margin:0 0 8px">Vraagt internet. Voor de lodge zelf: zoek op de hotelnaam.</p>${v51Nav(pt[2],pt[0],pt[1])}</div>${v51Info(d)}`}
  return v51PrevDC(d)};

/* hoofdkaart */
renderMap=function(){const td=v48TripDay();
  return `<div class="card v51-mapcard"><div class="v51-maphead"><div class="v50-h">Schematische routekaart</div>${v51GpsBox()}</div>${v51Svg(td||0)}${v51Legend()}<p class="hint" style="margin:6px 0 0">Werkt zonder internet. Tik een genummerde stop om die dag te openen. Je opgenomen GPS-routes verschijnen als groene lijn.</p></div>
  <div class="card"><div class="v50-h">Etappes</div>${V51_STOPS.slice(0,-1).map(([r,days],i)=>{const d0=S[days[0]-1],prev=i?V51_STOPS[i-1][0]:null,km=prev?Math.round(v51Dist(V51_PT[prev],V51_PT[r])):0;return `<button class="v51-leg" data-v51-day="${days[0]}"><span class="v51-n">${i+1}</span><span><b>${esc(V51_PT[r][2])}</b><small>Dag ${days.join(', ')} · ${fmt(d0.date)}${V51_TRAVEL[days[0]]?' · '+esc(V51_TRAVEL[days[0]].t):''}${km?' · ± '+km+' km hemelsbreed':''}</small></span>${v50I('chev',18).replace('<path','<path transform="rotate(-90 12 12)"')}</button>`}).join('')}</div>
  ${gpsPanel()}`};

/* ---------- valuta-omrekenaar ---------- */
state.v51Rates??={eurusd:1.1176,usdcrc:455.47,date:'12 okt 2026'};
function v51Fx(){const r=state.v51Rates;return `<div class="card v51-fx" id="v51fx"><div class="v50-h">${v50I('coin',20)} Valuta omrekenen</div>
  <div class="v51-fxrow"><label>EUR<input type="number" inputmode="decimal" data-v51-cur="eur" value="10"></label><label>USD<input type="number" inputmode="decimal" data-v51-cur="usd"></label><label>CRC<input type="number" inputmode="decimal" data-v51-cur="crc"></label></div>
  <div class="v51-quick">${[1000,5000,10000,20000].map(c=>`<button data-v51-crc="${c}">₡${c.toLocaleString('nl-NL')}</button>`).join('')}${[5,20,50].map(u=>`<button data-v51-usd="${u}">$${u}</button>`).join('')}</div>
  <details class="v51-rates"><summary>Koers: 1 EUR = ${String(r.eurusd).replace('.',',')} USD · 1 USD = ₡${String(r.usdcrc).replace('.',',')} <small>(${esc(r.date)})</small></summary>
  <div class="v51-fxrow"><label>1 EUR in USD<input type="number" step="0.0001" id="v51r1" value="${r.eurusd}"></label><label>1 USD in CRC<input type="number" step="0.01" id="v51r2" value="${r.usdcrc}"></label></div><button class="btn primary" id="v51rsave" style="width:100%;margin-top:8px">Koers opslaan</button>
  <p class="hint">Standaard: koers van 12 okt 2026 (Trading Economics). Werkt offline; pas aan met de koers ter plaatse.</p></details></div>`}
function v51FxCalc(src){const r=state.v51Rates,g=k=>document.querySelector(`[data-v51-cur="${k}"]`);if(!g('eur'))return;let eur;const v=parseFloat(g(src).value);if(isNaN(v)){return}
  eur=src==='eur'?v:src==='usd'?v/r.eurusd:v/r.usdcrc/r.eurusd;
  const f=(x,dg)=>(Math.round(x*10**dg)/10**dg);if(src!=='eur')g('eur').value=f(eur,2);if(src!=='usd')g('usd').value=f(eur*r.eurusd,2);if(src!=='crc')g('crc').value=Math.round(eur*r.eurusd*r.usdcrc)}

/* ---------- back-upstatus ---------- */
function v51BackupAge(){const t=state.v51LastBackup;return t?Math.floor((Date.now()-new Date(t))/864e5):null}
function v51BackupCard(){const a=v51BackupAge(),warn=a===null||a>14;return `<div class="card v51-backup ${warn?'warn':''}">${v50I(warn?'alert':'check',20)}<div><b>${a===null?'Nog geen back-up gemaakt':a===0?'Back-up gemaakt: vandaag':`Laatste back-up: ${a} ${a===1?'dag':'dagen'} geleden`}</b><span>Je notities, afvinklijsten en waarnemingen staan alleen in deze browser. Download regelmatig een back-up${warn?', zeker vóór vertrek':''}.</span></div></div>`}
const v51PrevSettings=renderSettings;
renderSettings=function(){return v51BackupCard()+v51Fx()+v51PrevSettings()};
const v51PrevHome=renderHome;
renderHome=function(){let h=v51PrevHome();const a=v51BackupAge();if(a===null||a>14)h=h.replace('<div class="home-section-title">',`<button class="v51-homewarn" data-goto="settings">${v50I('alert',16)}${a===null?'Nog geen back-up van je gegevens':'Back-up is '+a+' dagen oud'} · maak er nu een</button><div class="home-section-title">`);
  return h.replace(/<strong>Praktisch<\/strong><small>[^<]*<\/small>/,'<strong>Praktisch</strong><small>Valuta, info & back-up</small>')};

/* ---------- fototips prioriteitssoorten ---------- */
